<script lang="ts">
 import '$lib/styles/inquiry-interactions.css';
 import type { PageData } from './$types';
 import { STATES,INQUIRY_TYPES } from '$lib/inquiries';
 import { invalidateAll } from '$app/navigation';
 import AdminIcon from '$lib/components/admin/AdminIcon.svelte';
 let {data}:{data:PageData}=$props();
 const activeCount=$derived(data.counts.new+data.counts.working+data.counts.waiting);
 const href=(status:string,origin=data.origin,page=1)=>'?'+new URLSearchParams({status,origin,q:data.q,page:String(page)}).toString();
 const date=(s:string)=>new Date(s).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
</script>
<svelte:head><title>お問い合わせ | Book</title></svelte:head>
<div class="inbox">
 <header class="inbox-heading"><div><h1>お問い合わせ</h1></div><div class="inbox-actions"><a href="/admin/inquiries/ai" class="ai-settings-link">AI設定</a><span class="connection" class:warning={!!data.health?.last_error||!data.health?.last_sync_at}><i></i>{data.health?.last_error?'返信取り込みを確認':data.health?.last_sync_at?'メール連携中':'接続確認待ち'}</span><button onclick={()=>invalidateAll()}>更新</button></div></header>
 <div class="inbox-origins"><a class:active={data.origin==='current'} href={href('open','current')}><AdminIcon name="plan"/>受信トレイ</a><a class:active={data.origin==='history'} href={href('all','history')}><AdminIcon name="book"/>過去のやり取り</a></div>
 <div class="overview">{#each ['new','working','waiting','done','no_action'] as state}<a class="overview-stat" href={href(state)}><span><i class="dot-{state}"></i>{state==='waiting'?'返信待ち':STATES[state]}</span><strong>{data.counts[state as keyof typeof data.counts].toLocaleString()}</strong></a>{/each}</div>
 <section class="inbox-table" aria-label="問い合わせ一覧">
  <div class="table-toolbar"><nav aria-label="対応状況"><a class:active={data.status==='open'} href={href('open')}>対応中のすべて <span>{activeCount}</span></a><a class:active={data.status==='new'} href={href('new')}>未対応 <span>{data.counts.new}</span></a><a class:active={data.status==='done'} href={href('done')}>完了</a><a class:active={data.status==='no_action'} href={href('no_action')}>対応不要</a><a class:active={data.status==='all'} href={href('all')}>全件</a>{#if ['working','waiting'].includes(data.status)}<span class="custom-filter">{STATES[data.status]}</span>{/if}</nav><form method="get" role="search"><input type="hidden" name="origin" value={data.origin}/><input type="hidden" name="status" value={data.status}/><label class="sr-only" for="inquiry-search">お名前・件名・メールで検索</label><input id="inquiry-search" name="q" value={data.q} placeholder="お名前・件名・メールで検索" maxlength="80"/><button aria-label="検索"><AdminIcon name="eye"/></button></form></div>
  {#if data.unavailable}<div class="empty-state"><AdminIcon name="plan" class="h-7 w-7"/><h2>読み込みを確認してください</h2><p>{data.unavailable}</p></div>{:else if !data.items.length}<div class="empty-state"><span class="empty-icon"><AdminIcon name="shield" class="h-7 w-7"/></span><h2>{data.q?'該当するお問い合わせはありません':data.status==='open'?'対応が必要なお問い合わせはありません':'お問い合わせはありません'}</h2><p>{data.q?'検索条件を変えてお試しください。':''}</p>{#if data.status==='open'}<a href={href('all')}>すべてのやり取りを見る →</a>{/if}</div>{/if}
  {#if data.items.length}<div class="table-labels"><span>お客様 / お問い合わせ</span><span>状況</span><span>担当者</span><span>更新</span><span></span></div>{/if}
  <div>{#each data.items as item (item.id)}<a class="inquiry-row" href="/admin/inquiries/{item.id}"><div class="row-main"><span class="avatar" class:unread={item.status==='new'}>{item.name.slice(0,1)}</span><div class="row-copy"><div class="row-title"><strong>{item.subject||'お問い合わせ'}</strong>{#if ['pending','running'].includes(item.inquiry_draft_jobs?.state??'')}<span class="draft-tag generating">AI作成中</span>{:else if item.draft_origin==='auto'}<span class="draft-tag">AI下書きあり</span>{:else if item.draft_updated_at}<span class="draft-tag manual">下書きあり</span>{/if}</div>{#if INQUIRY_TYPES[item.profile.inquiry_type]}<span class="draft-tag type-tag">{INQUIRY_TYPES[item.profile.inquiry_type]}</span>{/if}<p class="guest-name">{item.name} 様 <span>·</span> {item.email}</p><p class="preview">{item.preview}</p></div></div><span class="status status-{item.status}"><i></i>{item.status==='waiting'?'お客様の返信待ち':STATES[item.status]}</span><span class="assignee">{item.assignee||'未割り当て'}</span><time>{date(item.updated_at)}</time><span class="row-arrow">→</span></a>{/each}</div>
  {#if !data.unavailable}<footer class="table-footer"><span>{data.page}ページ · {data.items.length}件を表示</span><nav aria-label="ページ送り">{#if data.page>1}<a href={href(data.status,data.origin,data.page-1)}>← 前へ</a>{/if}{#if data.more}<a href={href(data.status,data.origin,data.page+1)}>次へ →</a>{/if}</nav></footer>{/if}
 </section>
 <p class="inbox-footnote">事業者の方のお問い合わせはAI下書きの対象外です。{#if data.health?.last_sync_at}<span>最終メール同期 {date(data.health.last_sync_at)}</span>{/if}</p>
</div>
